CREATE OR REPLACE FUNCTION public.validate_table_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_distinct_count integer;
    v_total_capacity integer;
BEGIN

    IF NEW.restaurant_id IS NULL THEN
        RAISE EXCEPTION 'Skupina stolů musí mít restauraci';
    END IF;

    IF NEW.table_ids IS NULL
       OR cardinality(NEW.table_ids) = 0 THEN
        RAISE EXCEPTION 'Skupina stolů musí obsahovat alespoň jeden stůl';
    END IF;

    SELECT COUNT(DISTINCT x.table_id)::integer
    INTO v_distinct_count
    FROM unnest(NEW.table_ids) AS x(table_id);

    IF v_distinct_count <> cardinality(NEW.table_ids) THEN
        RAISE EXCEPTION 'Skupina stolů obsahuje duplicitní stůl';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(NEW.table_ids) AS x(table_id)
        LEFT JOIN public.restaurant_tables rt
          ON rt.id = x.table_id
         AND rt.restaurant_id = NEW.restaurant_id
         AND rt.active = true
        WHERE rt.id IS NULL
    ) THEN
        RAISE EXCEPTION
            'Skupina obsahuje neexistující, cizí nebo neaktivní stůl';
    END IF;

    SELECT COALESCE(SUM(rt.capacity), 0)::integer
    INTO v_total_capacity
    FROM public.restaurant_tables rt
    WHERE rt.restaurant_id = NEW.restaurant_id
      AND rt.active = true
      AND rt.id = ANY(NEW.table_ids);

    NEW.total_capacity := v_total_capacity;

    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.protect_restaurant_table_group_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_group_name text;
BEGIN

    -- ---------------------------------------------------------
    -- DELETE
    -- ---------------------------------------------------------
    IF TG_OP = 'DELETE' THEN

        -- Pokud se maže celá restaurace přes ON DELETE CASCADE,
        -- neblokujeme její interní cascade mazání.
        IF NOT EXISTS (
            SELECT 1
            FROM public.restaurants AS r
            WHERE r.id = OLD.restaurant_id
        ) THEN
            RETURN OLD;
        END IF;

        SELECT tg.name
        INTO v_group_name
        FROM public.table_groups AS tg
        WHERE tg.restaurant_id = OLD.restaurant_id
          AND OLD.id = ANY(tg.table_ids)
        ORDER BY tg.id
        LIMIT 1;

        IF FOUND THEN
            RAISE EXCEPTION
                'Stůl je součástí skupiny "%". Nejdříve ho odeberte ze skupiny.',
                v_group_name;
        END IF;

        RETURN OLD;
    END IF;


    -- ---------------------------------------------------------
    -- UPDATE
    -- ---------------------------------------------------------

    -- Zajímají nás pouze změny, které mohou rozbít skupinu:
    -- deaktivace, změna restaurant_id nebo změna id.
    IF NEW.active IS NOT DISTINCT FROM OLD.active
       AND NEW.restaurant_id IS NOT DISTINCT FROM OLD.restaurant_id
       AND NEW.id IS NOT DISTINCT FROM OLD.id THEN
        RETURN NEW;
    END IF;

    IF NEW.active = true
       AND NEW.restaurant_id IS NOT DISTINCT FROM OLD.restaurant_id
       AND NEW.id IS NOT DISTINCT FROM OLD.id THEN
        RETURN NEW;
    END IF;

    SELECT tg.name
    INTO v_group_name
    FROM public.table_groups AS tg
    WHERE tg.restaurant_id = OLD.restaurant_id
      AND OLD.id = ANY(tg.table_ids)
    ORDER BY tg.id
    LIMIT 1;

    IF FOUND THEN
        IF NEW.active = false
           AND OLD.active IS DISTINCT FROM NEW.active THEN

            RAISE EXCEPTION
                'Stůl je součástí skupiny "%". Nejdříve ho odeberte ze skupiny a potom ho deaktivujte.',
                v_group_name;

        ELSE

            RAISE EXCEPTION
                'Stůl je součástí skupiny "%". Dokud je ve skupině, nelze změnit jeho ID ani restauraci.',
                v_group_name;

        END IF;
    END IF;

    RETURN NEW;

END;
$function$
CREATE OR REPLACE FUNCTION public.consume_ai_daily_quota(p_restaurant_id bigint, p_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  accepted boolean;
  local_day date := (pg_catalog.now() at time zone 'Europe/Prague')::date;
begin
  if p_restaurant_id is null or p_restaurant_id <= 0 or p_kind not in ('guest','owner') or p_kind is null then
    raise exception 'Invalid AI quota request' using errcode='22023';
  end if;

  insert into public.ai_daily_quota as q
    (restaurant_id,kind,quota_date,request_count)
  values (p_restaurant_id,p_kind,local_day,1)
  on conflict (restaurant_id,kind,quota_date)
  do update set request_count=q.request_count+1
    where q.request_count < case when p_kind='guest' then 200 else 100 end
  returning true into accepted;

  return coalesce(accepted,false);
end;
$function$
CREATE OR REPLACE FUNCTION public.sync_table_group_capacities()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN

    UPDATE public.table_groups AS tg
    SET total_capacity = (
        SELECT COALESCE(SUM(rt.capacity), 0)::integer
        FROM public.restaurant_tables AS rt
        WHERE rt.restaurant_id = tg.restaurant_id
          AND rt.active = true
          AND rt.id = ANY(tg.table_ids)
    )
    WHERE tg.restaurant_id = NEW.restaurant_id
      AND NEW.id = ANY(tg.table_ids);

    RETURN NEW;

END;
$function$
