CREATE OR REPLACE FUNCTION public.create_owner_restaurant(p_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_email text;
  v_restaurant_id bigint;
  v_name text := btrim(p_name);
  v_slug text;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if v_name is null or char_length(v_name) < 2 or char_length(v_name) > 120 then
    raise exception 'Invalid restaurant name' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_user_id::text, 0));

  select lower(email) into v_email
  from auth.users
  where id = v_user_id and email_confirmed_at is not null;
  if v_email is null then
    raise exception 'Confirmed email required' using errcode = '28000';
  end if;

  if exists (select 1 from public.restaurant_team where user_id = v_user_id or lower(email) = v_email)
    or exists (select 1 from public.profiles where id = v_user_id and restaurant_id is not null) then
    raise exception 'Account already belongs to a restaurant' using errcode = '23505';
  end if;

  v_slug := 'restaurace-' || replace(v_user_id::text, '-', '');
  insert into public.restaurants (name, slug, is_published)
  values (v_name, v_slug, false)
  returning id into v_restaurant_id;

  insert into public.restaurant_team
    (restaurant_id, user_id, email, full_name, role, active, joined_at)
  values
    (v_restaurant_id, v_user_id, v_email, '', 'owner', true, now());

  return v_restaurant_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.sync_team_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account_email text;
  v_binding_changed boolean;
begin
  new.email := lower(btrim(new.email));
  new.updated_at := now();

  if new.user_id is not null then
    if tg_op = 'INSERT' then
      v_binding_changed := true;
    else
      v_binding_changed := old.user_id is distinct from new.user_id;
    end if;

    if v_binding_changed
       and coalesce(auth.role(), '') <> 'service_role'
       and auth.uid() is distinct from new.user_id then
      raise exception 'Only the account owner or trusted invitation service may bind a user'
        using errcode = '42501';
    end if;

    select lower(email) into v_account_email
    from auth.users
    where id = new.user_id;
    if v_account_email is null then
      raise exception 'Team user account does not exist' using errcode = '23503';
    end if;
    new.email := v_account_email;

    insert into public.profiles (id, restaurant_id, role)
    values (new.user_id, new.restaurant_id, new.role)
    on conflict (id) do update
      set restaurant_id = excluded.restaurant_id,
          role = excluded.role;
  end if;

  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.ensure_restaurant_has_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not old.active or lower(old.role) <> 'owner' or old.user_id is null then
    return null;
  end if;

  if tg_op = 'UPDATE'
     and new.restaurant_id = old.restaurant_id
     and new.active
     and lower(new.role) = 'owner'
     and new.user_id is not null then
    return null;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('last-owner:' || old.restaurant_id::text, 0)
  );

  if exists (select 1 from public.restaurants r where r.id = old.restaurant_id)
     and not exists (
       select 1 from public.restaurant_team t
       where t.restaurant_id = old.restaurant_id
         and t.active
         and lower(t.role) = 'owner'
         and t.user_id is not null
     ) then
    raise exception 'Restaurant must retain an active owner' using errcode = '23514';
  end if;

  return null;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_future_table_reservations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'Europe/Prague')::date;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Allow a restaurant's own ON DELETE CASCADE cleanup.
    IF NOT EXISTS (SELECT 1 FROM public.restaurants WHERE id = OLD.restaurant_id) THEN
      RETURN OLD;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.reservations r
      WHERE r.restaurant_id = OLD.restaurant_id
        AND r.table_id = OLD.id
        AND r.status <> 'Zrušeno'
        AND r.date >= v_today
    ) THEN
      RAISE EXCEPTION 'Stůl má budoucí rezervace. Nejdříve je přesuňte nebo zrušte.';
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.active = false AND OLD.active IS DISTINCT FROM NEW.active
    AND EXISTS (
      SELECT 1 FROM public.reservations r
      WHERE r.restaurant_id = OLD.restaurant_id
        AND r.table_id = OLD.id
        AND r.status <> 'Zrušeno'
        AND r.date >= v_today
    ) THEN
    RAISE EXCEPTION 'Stůl má budoucí rezervace. Nejdříve je přesuňte nebo zrušte.';
  END IF;

  IF NEW.capacity < OLD.capacity THEN
    IF EXISTS (
      SELECT 1 FROM public.reservations r
      WHERE r.restaurant_id = OLD.restaurant_id
        AND r.table_id = OLD.id
        AND r.status <> 'Zrušeno'
        AND r.date >= v_today
        AND r.people > NEW.capacity
    ) THEN
      RAISE EXCEPTION 'Nová kapacita stolu nestačí pro budoucí rezervaci.';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.table_groups g
      JOIN public.reservations r
        ON r.restaurant_id = g.restaurant_id
       AND r.table_group_id = g.id
      WHERE g.restaurant_id = OLD.restaurant_id
        AND OLD.id = ANY(g.table_ids)
        AND r.status <> 'Zrušeno'
        AND r.date >= v_today
        AND r.people > g.total_capacity - OLD.capacity + NEW.capacity
    ) THEN
      RAISE EXCEPTION 'Nová kapacita skupiny nestačí pro budoucí rezervaci.';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.can_manage_restaurant(target_restaurant_id bigint)
