CREATE OR REPLACE FUNCTION public.validate_restaurant_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.is_published IS NOT TRUE THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.is_published IS TRUE THEN
      RETURN NEW;
    END IF;
  END IF;

  IF nullif(btrim(NEW.name), '') IS NULL
     OR lower(btrim(NEW.name)) IN ('moje restaurace', 'my restaurant') THEN
    RAISE EXCEPTION 'Před zveřejněním zadejte skutečný název restaurace.';
  END IF;
  IF nullif(btrim(coalesce(NEW.address, '')), '') IS NULL
     AND nullif(btrim(coalesce(NEW.phone, '')), '') IS NULL
     AND nullif(btrim(coalesce(NEW.email, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Před zveřejněním doplňte adresu, telefon nebo e-mail restaurace.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.restaurant_tables t WHERE t.restaurant_id=NEW.id AND t.active=true)
     OR NOT EXISTS (SELECT 1 FROM public.opening_hours h WHERE h.restaurant_id=NEW.id AND h.is_open=true AND h.close_time > h.open_time)
     OR NOT EXISTS (SELECT 1 FROM public.reservation_settings s WHERE s.restaurant_id=NEW.id)
     OR NOT EXISTS (SELECT 1 FROM public.menu m WHERE m.restaurant_id=NEW.id) THEN
    RAISE EXCEPTION 'Před zveřejněním nastavte aktivní stůl, provozní dobu, pravidla rezervací a menu.';
  END IF;
  RETURN NEW;
END;
$function$
