CREATE OR REPLACE FUNCTION public.validate_reservation_assignment_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_capacity integer;
  v_active boolean;
BEGIN
  IF NEW.status = 'Zrušeno' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.status <> 'Zrušeno'
       AND NEW.status <> 'Zrušeno'
       AND OLD.restaurant_id IS NOT DISTINCT FROM NEW.restaurant_id
       AND OLD.people IS NOT DISTINCT FROM NEW.people
       AND OLD.table_id IS NOT DISTINCT FROM NEW.table_id
       AND OLD.table_group_id IS NOT DISTINCT FROM NEW.table_group_id THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.table_id IS NOT NULL THEN
    SELECT t.capacity,t.active INTO v_capacity,v_active
    FROM public.restaurant_tables t
    WHERE t.id=NEW.table_id AND t.restaurant_id=NEW.restaurant_id;
    IF v_capacity IS NULL OR v_active IS NOT TRUE THEN
      RAISE EXCEPTION 'Přiřazený stůl není aktivní nebo nepatří restauraci.';
    END IF;
    IF NEW.people > v_capacity THEN
      RAISE EXCEPTION 'Počet hostů překračuje kapacitu stolu.';
    END IF;
  ELSIF NEW.table_group_id IS NOT NULL THEN
    SELECT g.total_capacity,g.active INTO v_capacity,v_active
    FROM public.table_groups g
    WHERE g.id=NEW.table_group_id AND g.restaurant_id=NEW.restaurant_id;
    IF v_capacity IS NULL OR v_active IS NOT TRUE THEN
      RAISE EXCEPTION 'Přiřazená skupina stolů není aktivní nebo nepatří restauraci.';
    END IF;
    IF NEW.people > v_capacity THEN
      RAISE EXCEPTION 'Počet hostů překračuje kapacitu skupiny stolů.';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
