CREATE OR REPLACE FUNCTION public.check_public_reservation_rate_limit(p_rate_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_recent_10_minutes integer;
    v_recent_24_hours integer;
BEGIN
    -- Neplatný klíč odmítneme.
    IF p_rate_key IS NULL
       OR length(trim(p_rate_key)) < 10
       OR length(p_rate_key) > 300 THEN
        RETURN false;
    END IF;

    /*
      SERIALIZACE PRO STEJNÝ RATE KEY
      --------------------------------
      Pokud přijde více požadavků se stejným klíčem současně,
      pouze jeden z nich pokračuje. Ostatní počkají.

      Lock se automaticky uvolní na konci transakce.
    */
    PERFORM pg_advisory_xact_lock(
        hashtextextended(p_rate_key, 0)
    );

    -- Úklid starých záznamů.
    DELETE FROM public.public_reservation_rate_limits
    WHERE created_at < now() - interval '2 days';

    -- Počet pokusů za posledních 10 minut.
    SELECT count(*)
    INTO v_recent_10_minutes
    FROM public.public_reservation_rate_limits
    WHERE rate_key = p_rate_key
      AND created_at >= now() - interval '10 minutes';

    IF v_recent_10_minutes >= 3 THEN
        RETURN false;
    END IF;

    -- Počet pokusů za posledních 24 hodin.
    SELECT count(*)
    INTO v_recent_24_hours
    FROM public.public_reservation_rate_limits
    WHERE rate_key = p_rate_key
      AND created_at >= now() - interval '24 hours';

    IF v_recent_24_hours >= 10 THEN
        RETURN false;
    END IF;

    -- Tento pokus zapíšeme až po úspěšné kontrole.
    INSERT INTO public.public_reservation_rate_limits (rate_key)
    VALUES (p_rate_key);

    RETURN true;
END;
$function$
CREATE OR REPLACE FUNCTION public.prevent_reservation_double_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_requested_table_ids bigint[];
BEGIN
  -- Zrušená rezervace žádný stůl neblokuje.
  IF NEW.status = 'Zrušeno' THEN
    RETURN NEW;
  END IF;

  -- Běžná změna aktivního statusu (např. Čeká -> Potvrzeno)
  -- nemění čas ani obsazené stoly, proto ji nemusíme znovu kontrolovat.
  IF TG_OP = 'UPDATE'
     AND OLD.status <> 'Zrušeno'
     AND NEW.status <> 'Zrušeno'
     AND OLD.restaurant_id IS NOT DISTINCT FROM NEW.restaurant_id
     AND OLD.date IS NOT DISTINCT FROM NEW.date
     AND OLD.time IS NOT DISTINCT FROM NEW.time
     AND OLD.duration_minutes IS NOT DISTINCT FROM NEW.duration_minutes
     AND OLD.table_id IS NOT DISTINCT FROM NEW.table_id
     AND OLD.table_group_id IS NOT DISTINCT FROM NEW.table_group_id
  THEN
    RETURN NEW;
  END IF;

  IF NEW.restaurant_id IS NULL THEN
    RAISE EXCEPTION 'Rezervace musí mít restauraci';
  END IF;

  IF NEW.date IS NULL OR NEW.time IS NULL THEN
    RAISE EXCEPTION 'Rezervace musí mít datum a čas';
  END IF;

  IF NEW.duration_minutes IS NULL OR NEW.duration_minutes < 30 THEN
    RAISE EXCEPTION 'Rezervace musí mít platnou délku';
  END IF;

  IF NEW.table_id IS NOT NULL AND NEW.table_group_id IS NOT NULL THEN
    RAISE EXCEPTION 'Rezervace nemůže mít současně stůl i skupinu stolů';
  END IF;

  -- Pokud rezervace zatím nemá přiřazený žádný stůl, není co kontrolovat.
  IF NEW.table_id IS NULL AND NEW.table_group_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Zjistíme fyzické stoly, které nová rezervace skutečně obsadí.
  IF NEW.table_id IS NOT NULL THEN
    SELECT ARRAY[rt.id]::bigint[]
    INTO v_requested_table_ids
    FROM public.restaurant_tables AS rt
    WHERE rt.id = NEW.table_id
      AND rt.restaurant_id = NEW.restaurant_id
      AND rt.active = true;

    IF v_requested_table_ids IS NULL THEN
      RAISE EXCEPTION 'Stůl neexistuje, nepatří restauraci nebo není aktivní';
    END IF;
  ELSE
    SELECT tg.table_ids
    INTO v_requested_table_ids
    FROM public.table_groups AS tg
    WHERE tg.id = NEW.table_group_id
      AND tg.restaurant_id = NEW.restaurant_id;

    IF v_requested_table_ids IS NULL
       OR cardinality(v_requested_table_ids) = 0
    THEN
      RAISE EXCEPTION 'Skupina stolů neexistuje nebo je prázdná';
    END IF;

    -- Každý fyzický stůl ve skupině musí opravdu patřit stejné restauraci
    -- a musí být aktivní.
    IF EXISTS (
      SELECT 1
      FROM unnest(v_requested_table_ids) AS requested_table_id
      LEFT JOIN public.restaurant_tables AS rt
        ON rt.id = requested_table_id
       AND rt.restaurant_id = NEW.restaurant_id
       AND rt.active = true
      WHERE rt.id IS NULL
    ) THEN
      RAISE EXCEPTION 'Skupina obsahuje neplatný, cizí nebo neaktivní stůl';
    END IF;
  END IF;

  -- Serializujeme rezervace restaurace i mezi sousedními dny.
  -- Tím zavřeme race condition při dvou téměř současných zápisech.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      NEW.restaurant_id::text,
      0
    )
  );

  -- Konflikt nastane, když se překrývá čas A ZÁROVEŇ je společný
  -- alespoň jeden fyzický stůl.
  IF EXISTS (
    SELECT 1
    FROM public.reservations AS existing
    LEFT JOIN public.table_groups AS existing_group
      ON existing_group.id = existing.table_group_id
     AND existing_group.restaurant_id = existing.restaurant_id
    WHERE existing.restaurant_id = NEW.restaurant_id
      AND existing.date BETWEEN NEW.date - 1 AND NEW.date + 1
      AND existing.status <> 'Zrušeno'
      AND existing.id <> COALESCE(NEW.id, -1)
      AND (existing.date + existing.time::time)
          < (NEW.date + NEW.time::time + make_interval(mins => NEW.duration_minutes))
      AND (existing.date + existing.time::time
          + make_interval(mins => existing.duration_minutes))
          > (NEW.date + NEW.time::time)
      AND (
        (
          existing.table_id IS NOT NULL
          AND existing.table_id = ANY(v_requested_table_ids)
        )
        OR
        (
          existing.table_group_id IS NOT NULL
          AND existing_group.table_ids && v_requested_table_ids
        )
      )
  ) THEN
    RAISE EXCEPTION 'Vybraný stůl nebo skupina stolů je v tomto čase již rezervovaná';
  END IF;

  RETURN NEW;
END;
$function$
