CREATE OR REPLACE FUNCTION public.create_public_reservation(p_slug text, p_name text, p_people integer, p_date date, p_time text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_table_id bigint DEFAULT NULL::bigint, p_table_group_id bigint DEFAULT NULL::bigint)
 RETURNS reservations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_restaurant_id bigint;
    v_settings public.reservation_settings%ROWTYPE;
    v_duration integer;
    v_start_time time;
    v_start_at timestamp;
    v_result public.reservations%ROWTYPE;

    v_requested_table_ids bigint[];
    v_capacity integer;
    v_distinct_table_count integer;
    v_prague_today date;
BEGIN

    -- ---------------------------------------------------------
    -- 1. Základní validace vstupů
    -- ---------------------------------------------------------

    IF btrim(coalesce(p_slug, '')) = '' THEN
        RAISE EXCEPTION 'Restaurace není určena';
    END IF;

    IF btrim(coalesce(p_name, '')) = '' THEN
        RAISE EXCEPTION 'Jméno je povinné';
    END IF;

    IF p_people IS NULL THEN
        RAISE EXCEPTION 'Počet hostů je povinný';
    END IF;

    IF p_date IS NULL THEN
        RAISE EXCEPTION 'Datum je povinné';
    END IF;

    IF btrim(coalesce(p_time, '')) = '' THEN
        RAISE EXCEPTION 'Čas je povinný';
    END IF;

    IF p_time !~ '^([01]?[0-9]|2[0-3]):[0-5][0-9]$' THEN
        RAISE EXCEPTION 'Neplatný formát času';
    END IF;

    IF btrim(coalesce(p_phone, '')) = ''
       AND btrim(coalesce(p_email, '')) = '' THEN
        RAISE EXCEPTION 'Je nutný telefon nebo e-mail';
    END IF;

    IF p_table_id IS NOT NULL
       AND p_table_group_id IS NOT NULL THEN
        RAISE EXCEPTION 'Nelze současně vybrat stůl i skupinu stolů';
    END IF;

    -- Veřejná rezervace musí vždy skutečně blokovat
    -- konkrétní fyzický stůl nebo skupinu stolů.
    IF p_table_id IS NULL
       AND p_table_group_id IS NULL THEN
        RAISE EXCEPTION 'Rezervace musí mít přiřazený stůl nebo skupinu stolů';
    END IF;


    -- ---------------------------------------------------------
    -- 2. Restaurace podle slugu
    -- ---------------------------------------------------------

    SELECT r.id
    INTO v_restaurant_id
    FROM public.restaurants AS r
    WHERE r.slug = btrim(p_slug)
      AND r.is_published = true;

    IF v_restaurant_id IS NULL THEN
        RAISE EXCEPTION 'Restaurace neexistuje nebo není zveřejněná';
    END IF;


    -- ---------------------------------------------------------
    -- 3. Nastavení rezervací
    -- ---------------------------------------------------------

    SELECT rs.*
    INTO v_settings
    FROM public.reservation_settings AS rs
    WHERE rs.restaurant_id = v_restaurant_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Restaurace nemá nastavení rezervací';
    END IF;

    IF p_people < v_settings.min_people
       OR p_people > v_settings.max_people THEN
        RAISE EXCEPTION 'Neplatný počet hostů';
    END IF;

    v_duration :=
        CASE
            WHEN p_people <= 2 THEN v_settings.duration_1_2
            WHEN p_people <= 4 THEN v_settings.duration_3_4
            WHEN p_people <= 6 THEN v_settings.duration_5_6
            ELSE v_settings.duration_7_plus
        END;

    IF v_duration IS NULL
       OR v_duration < 30
       OR v_duration > 360 THEN
        RAISE EXCEPTION 'Restaurace má neplatnou délku rezervace';
    END IF;

    v_start_time := p_time::time;
    v_start_at := p_date + v_start_time;

    v_prague_today :=
        timezone('Europe/Prague', now())::date;


    -- ---------------------------------------------------------
    -- 4. Datum a minimální předstih
    -- ---------------------------------------------------------

    IF p_date > v_prague_today + v_settings.max_advance_days THEN
        RAISE EXCEPTION 'Datum je příliš daleko';
    END IF;

    IF v_start_at <
       timezone('Europe/Prague', now())
       + make_interval(mins => v_settings.min_advance_minutes) THEN
        RAISE EXCEPTION 'Rezervace nesplňuje minimální předstih';
    END IF;


    -- ---------------------------------------------------------
    -- 5. Otevírací doba
    -- ---------------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM public.opening_hours AS oh
        WHERE oh.restaurant_id = v_restaurant_id
          AND oh.day_of_week = extract(dow FROM p_date)::integer
          AND oh.is_open = true
          AND v_start_time >= oh.open_time
          AND v_start_at + make_interval(mins => v_duration)
              <= p_date + oh.close_time
    ) THEN
        RAISE EXCEPTION 'Restaurace je v tomto čase zavřená';
    END IF;


    -- ---------------------------------------------------------
    -- 6. Blokované časy
    -- ---------------------------------------------------------

    IF EXISTS (
        SELECT 1
        FROM public.blocked_times AS bt
        WHERE bt.restaurant_id = v_restaurant_id
          AND bt.date = p_date
          AND v_start_time < bt.end_time
          AND v_start_at + make_interval(mins => v_duration)
              > p_date + bt.start_time
    ) THEN
        RAISE EXCEPTION 'Tento čas je blokovaný';
    END IF;


    -- ---------------------------------------------------------
    -- 7. Samostatný stůl
    -- ---------------------------------------------------------

    IF p_table_id IS NOT NULL THEN

        SELECT
            ARRAY[rt.id]::bigint[],
            rt.capacity
        INTO
            v_requested_table_ids,
            v_capacity
        FROM public.restaurant_tables AS rt
        WHERE rt.id = p_table_id
          AND rt.restaurant_id = v_restaurant_id
          AND rt.active = true;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Stůl neexistuje, nepatří restauraci nebo není aktivní';
        END IF;

        IF v_capacity < p_people THEN
            RAISE EXCEPTION
                'Vybraný stůl nemá dostatečnou kapacitu';
        END IF;

    END IF;


    -- ---------------------------------------------------------
    -- 8. Skupina stolů
    -- ---------------------------------------------------------

    IF p_table_group_id IS NOT NULL THEN

        SELECT tg.table_ids
        INTO v_requested_table_ids
        FROM public.table_groups AS tg
        WHERE tg.id = p_table_group_id
          AND tg.restaurant_id = v_restaurant_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Skupina stolů neexistuje nebo nepatří restauraci';
        END IF;

        IF v_requested_table_ids IS NULL
           OR cardinality(v_requested_table_ids) = 0 THEN
            RAISE EXCEPTION
                'Skupina stolů neobsahuje žádné stoly';
        END IF;


        -- Žádné duplicitní ID stolu ve skupině.
        SELECT count(DISTINCT u.table_id)::integer
        INTO v_distinct_table_count
        FROM unnest(v_requested_table_ids) AS u(table_id);

        IF v_distinct_table_count
           <> cardinality(v_requested_table_ids) THEN
            RAISE EXCEPTION
                'Skupina stolů obsahuje duplicitní stůl';
        END IF;


        -- Každý fyzický stůl musí existovat,
        -- patřit stejné restauraci a být aktivní.
        IF EXISTS (
            SELECT 1
            FROM unnest(v_requested_table_ids) AS u(table_id)
            LEFT JOIN public.restaurant_tables AS rt
              ON rt.id = u.table_id
             AND rt.restaurant_id = v_restaurant_id
             AND rt.active = true
            WHERE rt.id IS NULL
        ) THEN
            RAISE EXCEPTION
                'Skupina obsahuje neexistující, cizí nebo neaktivní stůl';
        END IF;


        -- Reálná kapacita se počítá ze skutečných stolů.
        SELECT COALESCE(SUM(rt.capacity), 0)::integer
        INTO v_capacity
        FROM public.restaurant_tables AS rt
        WHERE rt.restaurant_id = v_restaurant_id
          AND rt.active = true
          AND rt.id = ANY(v_requested_table_ids);

        IF v_capacity < p_people THEN
            RAISE EXCEPTION
                'Skupina stolů nemá dostatečnou kapacitu';
        END IF;

    END IF;


    -- ---------------------------------------------------------
    -- 9. Serializace rezervací restaurace i přes hranici dnů
    -- ---------------------------------------------------------

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            v_restaurant_id::text,
            0
        )
    );


    -- ---------------------------------------------------------
    -- 10. Double-booking přes skutečné fyzické stoly
    -- ---------------------------------------------------------

    IF v_requested_table_ids IS NOT NULL
       AND cardinality(v_requested_table_ids) > 0
       AND EXISTS (
            SELECT 1
            FROM public.reservations AS existing

            LEFT JOIN public.table_groups AS existing_group
              ON existing_group.id = existing.table_group_id
             AND existing_group.restaurant_id =
                 existing.restaurant_id

            WHERE existing.restaurant_id = v_restaurant_id
              AND existing.date BETWEEN p_date - 1 AND p_date + 1
              AND existing.status <> 'Zrušeno'

              AND (existing.date + existing.time::time)
                  < (v_start_at + make_interval(mins => v_duration))

              AND (existing.date + existing.time::time
                  + make_interval(mins => existing.duration_minutes))
                  > v_start_at

              AND (
                    (
                        existing.table_id IS NOT NULL
                        AND existing.table_id =
                            ANY(v_requested_table_ids)
                    )
                    OR
                    (
                        existing.table_group_id IS NOT NULL
                        AND existing_group.table_ids
                            && v_requested_table_ids
                    )
              )
       ) THEN
        RAISE EXCEPTION
            'Vybraný stůl nebo skupina stolů je v tomto čase již rezervovaná';
    END IF;


    -- ---------------------------------------------------------
    -- 11. Vytvoření rezervace
    -- ---------------------------------------------------------

    INSERT INTO public.reservations (
        name,
        last_name,
        people,
        date,
        time,
        phone,
        email,
        note,
        table_id,
        table_group_id,
        restaurant_id,
        duration_minutes,
        status
    )
    VALUES (
        btrim(p_name),
        nullif(btrim(coalesce(p_last_name, '')), ''),
        p_people,
        p_date,
        to_char(v_start_time, 'HH24:MI'),
        nullif(btrim(coalesce(p_phone, '')), ''),
        nullif(btrim(coalesce(p_email, '')), ''),
        nullif(btrim(coalesce(p_note, '')), ''),
        p_table_id,
        p_table_group_id,
        v_restaurant_id,
        v_duration,
        'Čeká'
    )
    RETURNING *
    INTO v_result;

    RETURN v_result;

END;
$function$
