CREATE OR REPLACE FUNCTION public.check_public_reservation_ip_rate_limit(p_rate_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_recent_10_minutes integer;
    v_recent_24_hours integer;
BEGIN
    -- Neplatný klíč odmítneme.
    IF p_rate_key IS NULL
       OR length(trim(p_rate_key)) < 10
       OR length(p_rate_key) > 300 THEN
        RETURN false;
    END IF;

    -- Souběžné requesty se stejným IP klíčem
    -- zpracujeme postupně.
    PERFORM pg_advisory_xact_lock(
        hashtextextended(p_rate_key, 0)
    );

    -- Úklid starých záznamů.
    DELETE FROM public.public_reservation_rate_limits
    WHERE created_at < now() - interval '2 days';

    -- Vyšší limit pro jednu IP:
    -- maximálně 10 pokusů za 10 minut.
    SELECT count(*)
    INTO v_recent_10_minutes
    FROM public.public_reservation_rate_limits
    WHERE rate_key = p_rate_key
      AND created_at >= now() - interval '10 minutes';

    IF v_recent_10_minutes >= 10 THEN
        RETURN false;
    END IF;

    -- Maximálně 30 pokusů za 24 hodin z jedné IP
    -- pro konkrétní restauraci.
    SELECT count(*)
    INTO v_recent_24_hours
    FROM public.public_reservation_rate_limits
    WHERE rate_key = p_rate_key
      AND created_at >= now() - interval '24 hours';

    IF v_recent_24_hours >= 30 THEN
        RETURN false;
    END IF;

    INSERT INTO public.public_reservation_rate_limits (rate_key)
    VALUES (p_rate_key);

    RETURN true;
END;
