CREATE OR REPLACE FUNCTION public.require_restaurant_ready_on_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.is_published is true
     and old.is_published is distinct from true
  then
    if lower(btrim(coalesce(new.name, ''))) in ('', 'moje restaurace', 'my restaurant') then
      raise exception 'Před zveřejněním zadejte skutečný název restaurace.'
        using errcode = '23514';
    end if;

    if not exists (
         select 1 from public.restaurant_tables t
         where t.restaurant_id = new.id and t.active is true
       )
       or not exists (
         select 1 from public.opening_hours h
         where h.restaurant_id = new.id
           and h.is_open is true
           and h.open_time is not null
           and h.close_time is not null
       )
       or not exists (
         select 1 from public.reservation_settings s
         where s.restaurant_id = new.id
       )
       or not exists (
         select 1 from public.menu m
         where m.restaurant_id = new.id
       )
    then
      raise exception 'Před zveřejněním nastavte aktivní stůl, otevřený den, pravidla rezervací a menu.'
        using errcode = '23514';
    end if;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.log_reservation_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  claims jsonb := '{}'::jsonb;
  request_headers jsonb := '{}'::jsonb;
  actor_value uuid;
  email_value text;
  target_restaurant_id bigint;
begin
  begin
    claims := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
    request_headers := coalesce(nullif(current_setting('request.headers', true), '')::jsonb, '{}'::jsonb);
  exception when others then
    claims := '{}'::jsonb;
    request_headers := '{}'::jsonb;
  end;

  actor_value := auth.uid();
  email_value := claims ->> 'email';
  if tg_op = 'DELETE' then
    target_restaurant_id := old.restaurant_id;
  else
    target_restaurant_id := new.restaurant_id;
  end if;

  if claims ->> 'role' = 'service_role'
     and nullif(request_headers ->> 'x-audit-actor-id', '') is not null then
    actor_value := (request_headers ->> 'x-audit-actor-id')::uuid;
    select u.email into email_value
    from auth.users u
    join public.restaurant_team t
      on t.user_id = u.id
     and t.restaurant_id = target_restaurant_id
     and t.active = true
    where u.id = actor_value
    limit 1;
    if not found then
      raise exception 'RESERVATION_AUDIT_ACTOR_NOT_ACTIVE'
        using errcode = 'P0001';
    end if;
  end if;

  if tg_op = 'INSERT' then
    insert into public.reservation_history (
      restaurant_id, reservation_id, reservation_name, action,
      before_data, after_data, actor_id, actor_email
    ) values (
      new.restaurant_id, new.id, new.name, 'created',
      null, to_jsonb(new), actor_value, email_value
    );
    return new;
  elsif tg_op = 'UPDATE' then
    if to_jsonb(old) is distinct from to_jsonb(new) then
      insert into public.reservation_history (
        restaurant_id, reservation_id, reservation_name, action,
        before_data, after_data, actor_id, actor_email
      ) values (
        new.restaurant_id, new.id, new.name, 'updated',
        to_jsonb(old), to_jsonb(new), actor_value, email_value
      );
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    insert into public.reservation_history (
      restaurant_id, reservation_id, reservation_name, action,
      before_data, after_data, actor_id, actor_email
    ) values (
      old.restaurant_id, old.id, old.name, 'deleted',
      to_jsonb(old), null, actor_value, email_value
    );
    return old;
  end if;
  return null;
end;
$function$
CREATE OR REPLACE FUNCTION public.get_public_reservation_settings(p_slug text)
 RETURNS TABLE(duration_1_2 integer, duration_3_4 integer, duration_5_6 integer, duration_7_plus integer, min_advance_minutes integer, max_advance_days integer, min_people integer, max_people integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
    SELECT
        rs.duration_1_2,
        rs.duration_3_4,
        rs.duration_5_6,
        rs.duration_7_plus,
        rs.min_advance_minutes,
        rs.max_advance_days,
        rs.min_people,
        rs.max_people
    FROM public.reservation_settings AS rs
    JOIN public.restaurants AS r
      ON r.id = rs.restaurant_id
    WHERE r.slug = p_slug
      AND r.is_published = true;
$function$
CREATE OR REPLACE FUNCTION public.get_public_menu_safe(p_slug text)
 RETURNS TABLE(id bigint, name text, price integer, emoji text, image_url text, category text, description text, ingredients text, allergens text, weight text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
    SELECT
        m.id,
        m.name,
        m.price,
        m.emoji,
        m.image_url,
        m.category,
        m.description,
        m.ingredients,
        m.allergens,
        m.weight
    FROM public.menu AS m
    JOIN public.restaurants AS r
      ON r.id = m.restaurant_id
    WHERE r.slug = p_slug
      AND r.is_published = true
    ORDER BY m.category, m.name;
$function$
CREATE OR REPLACE FUNCTION public.get_public_opening_hours_safe(p_slug text)
 RETURNS TABLE(id bigint, day_of_week integer, is_open boolean, open_time time without time zone, close_time time without time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
    SELECT
        oh.id,
        oh.day_of_week,
        oh.is_open,
        oh.open_time,
        oh.close_time
    FROM public.opening_hours AS oh
    JOIN public.restaurants AS r
      ON r.id = oh.restaurant_id
    WHERE r.slug = p_slug
