CREATE OR REPLACE FUNCTION public.get_public_restaurant_tables_safe(p_slug text)
 RETURNS TABLE(id bigint, name text, capacity integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
    SELECT
        rt.id,
        rt.name,
        rt.capacity
    FROM public.restaurant_tables AS rt
    JOIN public.restaurants AS r
