CREATE OR REPLACE FUNCTION public.create_public_reservation_with_locale(p_slug text, p_name text, p_people integer, p_date date, p_time text, p_phone text, p_email text, p_note text, p_last_name text, p_table_id bigint, p_table_group_id bigint, p_locale text)
 RETURNS TABLE(id bigint, status text, reservation_date date, reservation_time text, duration_minutes integer)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  created record;
begin
  if p_locale not in ('cs', 'en') or p_locale is null then
    raise exception 'Unsupported reservation locale' using errcode = '22023';
  end if;

  select * into strict created
  from public.create_public_reservation_safe(
    p_slug, p_name, p_people, p_date, p_time, p_phone, p_email,
    p_note, p_last_name, p_table_id, p_table_group_id
  );

  update public.reservations r
     set locale = p_locale
   where r.id = created.id;

  if not found then
    raise exception 'Reservation locale could not be saved' using errcode = 'P0001';
  end if;

  return query
    select created.id::bigint, created.status::text,
           created.reservation_date::date, created.reservation_time::text,
           created.duration_minutes::integer;
end;
$function$
